// The MCP clients' marks as inline SVG, from the sources the prototype used:
// Dashboard Icons, Simple Icons, Lobe Icons and the vendors' own files. A mark
// paints its parts with var(--mark-ink, <own colour>), so a lit README button
// turns it into the tile's ink; `hover` is the brand's single-colour version
// for a mark whose layers do not survive one ink. Jan's hand is the vendor's
// raster icon wrapped in SVG.

export interface ClientMark {
  rest: string;
  hover?: string;
}

